const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const root = $input.first().json;
const payload = root.payload || {};

const demoContact = {
  firstName: 'Casey',
  lastName: 'Morgan',
  email: 'casey@example.com',
  company: 'Brightline',
  jobTitle: 'Operations Director',
  lastContactAt: new Date(Date.now() - 4 * 86400000).toISOString(),
  attempts: 1,
  replied: false,
  optedOut: false,
  leadStatus: 'contacted',
  source: 'demo'
};

const contact = {
  firstName: payload.firstName || demoContact.firstName,
  lastName: payload.lastName || demoContact.lastName,
  email: payload.email || demoContact.email,
  company: payload.company || demoContact.company,
  jobTitle: payload.jobTitle || demoContact.jobTitle,
  lastContactAt: payload.lastContactAt || demoContact.lastContactAt,
  attempts: Number(payload.attempts ?? demoContact.attempts),
  replied: Boolean(payload.replied ?? demoContact.replied),
  optedOut: Boolean(payload.optedOut ?? demoContact.optedOut),
  leadStatus: payload.leadStatus || demoContact.leadStatus,
  source: payload.source || demoContact.source
};

return [
  {
    json: {
      ...root,
      contact
    }
  }
];

const d=$input.first().json,c=d.contact;
const days=Math.floor((Date.now()-new Date(c.lastContactAt).getTime())/86400000);
let action='wait';
if(c.optedOut) action='stop';
else if(c.replied) action='handoff';
else if(c.attempts>=4) action='close_sequence';
else if(days>=3) action='send_follow_up';
const nextAttempt=c.attempts+1;
return [{json:{...d,followUp:{action,daysSinceContact:days,nextAttempt}}}];

const previous = $('Determine Follow-Up Action').first().json;
const ai = $input.first().json;

const aiText =
  ai.output?.[0]?.content?.[0]?.text ||
  ai.content?.[0]?.text ||
  ai.text ||
  '';

const subjectMatch = aiText.match(/Subject:\s*(.+)/i);

const subject = subjectMatch
  ? subjectMatch[1].trim()
  : `Follow-up for ${previous.contact.company}`;

const body = aiText.replace(/Subject:.*?\n/i, '').trim();

return [
  {
    json: {
      ...previous,
      result: {
        action: previous.followUp.action,
        sendEligible: previous.followUp.action === 'send_follow_up',
        subject,
        message: body,
        generatedBy: 'OpenAI GPT-5',
        generatedAt: new Date().toISOString()
      }
    }
  }
];

